kansasinsuranceappraiser.com/claim-appraisal-services/home-insurance-claim-appraiser/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Claim Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/commercial-hoa-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Wind Damage Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/tornado-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane Remnant & Tropical Storm Claims","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/hurricane-remnant-wind-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/water-damage-claim-appraiser/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/fire-smoke-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Storm & Freeze Damage Appraisal","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/ice-storm-freeze-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Umpire Services","url":"https://arkansasinsuranceappraiser.com/claim-appraisal-services/appraisal-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Tornado damage","Ice storm damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://arkansasinsuranceappraiser.com/#website","url":"https://arkansasinsuranceappraiser.com/","name":"Arkansas Insurance Appraiser","publisher":{"@id":"https://arkansasinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://arkansasinsuranceappraiser.com/faq/#webpage","url":"https://arkansasinsuranceappraiser.com/faq/","name":"Insurance Appraisal FAQ | Arkansas Policyholders","description":"Insurance appraisal FAQ for Arkansas: how appraisal works, what it costs, deadlines, ARRUA, the Insurance Department and when appraisal doesn’t fit.","inLanguage":"en-US","isPartOf":{"@id":"https://arkansasinsuranceappraiser.com/#website"},"about":{"@id":"https://arkansasinsuranceappraiser.com/#business"},"publisher":{"@id":"https://arkansasinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@id":"https://arkansasinsuranceappraiser.com/faq/#primaryimage"},"breadcrumb":{"@id":"https://arkansasinsuranceappraiser.com/faq/#breadcrumb"},"mainEntity":{"@id":"https://arkansasinsuranceappraiser.com/faq/#faq"}},{"@type":"ImageObject","@id":"https://arkansasinsuranceappraiser.com/faq/#primaryimage","url":"https://arkansasinsuranceappraiser.com/assets/img/photos/consultation.webp","contentUrl":"https://arkansasinsuranceappraiser.com/assets/img/photos/consultation.webp","width":1024,"height":683,"caption":"Two people shaking hands across a table after a consultation"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://arkansasinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"FAQ","item":"https://arkansasinsuranceappraiser.com/faq/"}],"@id":"https://arkansasinsuranceappraiser.com/faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process in most property policies for resolving disagreements over the amount of a covered loss. Each side names an appraiser, the appraisers pick an umpire, and two signatures set the amount."}},{"@type":"Question","name":"When is appraisal the right tool?","acceptedAnswer":{"@type":"Answer","text":"When coverage is accepted and the dispute is about scope or price, such as repair versus replacement, missing line items, pricing or depreciation."}},{"@type":"Question","name":"When is appraisal the wrong tool?","acceptedAnswer":{"@type":"Answer","text":"When the claim is denied outright, when the dispute is whether a cause of loss is covered, or when the gap is too small to justify appraisal costs."}},{"@type":"Question","name":"Is the award binding?","acceptedAnswer":{"@type":"Answer","text":"Generally yes, on the amount of loss for the items submitted, once two of the three panel members sign. Courts can set aside awards in limited situations such as fraud or a panel exceeding its authority."}},{"@type":"Question","name":"Who pays for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Under most policies each side pays its own appraiser and shares the umpire’s fee equally."}},{"@type":"Question","name":"How do appraisers charge?","acceptedAnswer":{"@type":"Answer","text":"Hourly, a flat fee or a percentage of the increase over the carrier’s estimate. Ask for the arrangement in writing."}},{"@type":"Question","name":"Is the first conversation free?","acceptedAnswer":{"@type":"Answer","text":"Yes. We review the basics of your claim and tell you honestly whether appraisal is likely to help."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals finish within one to three months. Large or complex claims take longer."}},{"@type":"Question","name":"Does invoking appraisal pause my policy deadlines?","acceptedAnswer":{"@type":"Answer","text":"Don’t assume so. Suit-limitation and replacement-cost deadlines may keep running. Calendar them and ask an attorney about tolling if a deadline is close."}},{"@type":"Question","name":"How quickly must I name an appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies say within 20 days of a written demand. Read your policy and act quickly."}},{"@type":"Question","name":"Who regulates insurers in Arkansas?","acceptedAnswer":{"@type":"Answer","text":"The Arkansas Insurance Department. It handles licensing, rate filings and consumer complaints."}},{"@type":"Question","name":"Does Arkansas have a FAIR plan or wind pool?","acceptedAnswer":{"@type":"Answer","text":"Arkansas is inland and has no coastal wind pool. Its statutory residual market is the Arkansas Rural Risk Underwriting Association (ARRUA), which provides basic property coverage for qualifying risks in designated rural areas."}},{"@type":"Question","name":"What does Arkansas law say about insurer delays?","acceptedAnswer":{"@type":"Answer","text":"Arkansas has a statute that can add a statutory penalty and attorney’s fees when an insurer fails to pay a covered loss within the required time after demand, and courts recognize bad-faith claims in limited situations. These are legal questions for an Arkansas attorney."}},{"@type":"Question","name":"Can labor be depreciated in an Arkansas claim?","acceptedAnswer":{"@type":"Answer","text":"Arkansas courts have addressed labor depreciation in actual cash value payments, and the rules have developed over time. Ask the carrier how depreciation was calculated and talk to an attorney if it matters to your claim."}},{"@type":"Question","name":"Are you public adjusters or attorneys?","acceptedAnswer":{"@type":"Answer","text":"Neither. We are appraisers and estimators. We don’t negotiate claims outside appraisal and don’t give legal advice."}},{"@type":"Question","name":"Do you work statewide?","acceptedAnswer":{"@type":"Answer","text":"Yes, in all 75 Arkansas counties, from Benton County in the northwest to Chicot County in the southeast."}},{"@type":"Question","name":"What should I send first?","acceptedAnswer":{"@type":"Answer","text":"Your declarations page, the carrier’s full estimate, any letters from the carrier, your photos and any contractor estimate."}}],"@id":"https://arkansasinsuranceappraiser.com/faq/#faq"}]}</script>
</head>
